// This file is generated by AI.

// 本地图片 -> 可显示的 URL: 直接读字节造 blob URL, 用完就撤。
//
// 不借预览服务器: 开始界面还没有打开任何项目, 为十几张封面缩略图去注册十几个静态站点代价
// 太大 (而且这些站点会一直留着)。
//
// `readImageUrl` 是纯逻辑 (可单测); 响应式的 `useImageUrl` 依赖 rune, 因此本文件是 `.svelte.ts`。

import { fs } from './fs';

/** 由扩展名推断 MIME 类型 (读不到就交给浏览器猜)。 */
export function imageMimeType(path: string): string | undefined {
  const ext = path.slice(path.lastIndexOf('.') + 1).toLowerCase();
  switch (ext) {
    case 'png':
      return 'image/png';
    case 'jpg':
    case 'jpeg':
      return 'image/jpeg';
    case 'gif':
      return 'image/gif';
    case 'webp':
      return 'image/webp';
    case 'bmp':
      return 'image/bmp';
    case 'svg':
      return 'image/svg+xml';
    case 'avif':
      return 'image/avif';
    // 音频与视频也走同一条"读字节 -> blob URL"的路子 (配音试听、参考音频)
    case 'wav':
      return 'audio/wav';
    case 'mp3':
      return 'audio/mpeg';
    case 'ogg':
      return 'audio/ogg';
    case 'm4a':
      return 'audio/mp4';
    case 'flac':
      return 'audio/flac';
    case 'mp4':
      return 'video/mp4';
    case 'webm':
      return 'video/webm';
    default:
      return undefined;
  }
}

/**
 * 读文件并造一个 blob URL。
 *
 * 调用方负责在不用时 `URL.revokeObjectURL` —— 返回的是所有权已经转移的 URL。
 * 读不到时返回 null 而不是抛错: 封面缺失是常态 (项目里可能没配 `Title_img`)。
 */
export async function readImageUrl(path: string): Promise<string | null> {
  try {
    const bytes = await fs.readBytes(path);
    const mime = imageMimeType(path);
    // 显式取底层 ArrayBuffer 再交给 Blob: `Uint8Array<ArrayBufferLike>` 可能是 SharedArrayBuffer
    // 支撑的视图, 而 BlobPart 只接受 ArrayBuffer 支撑的那些。
    const buffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer;
    const blob = new Blob([buffer], mime ? { type: mime } : undefined);
    return URL.createObjectURL(blob);
  } catch {
    return null;
  }
}

/**
 * 响应式版本: 路径变化时重新读, 组件卸载或路径变化时撤销上一个 URL。
 *
 * `path` 为 null 表示"没有封面", 不读也不产生 URL。
 */
export function useImageUrl(getPath: () => string | null): { readonly url: string | null } {
  let url = $state<string | null>(null);

  $effect(() => {
    const path = getPath();
    let cancelled = false;
    let created: string | null = null;

    if (path) {
      void readImageUrl(path).then((next) => {
        if (cancelled) {
          // 读盘期间路径又变了 / 组件卸载了: 这个 URL 没人要, 立刻撤销, 否则泄漏
          if (next) URL.revokeObjectURL(next);
          return;
        }
        created = next;
        url = next;
      });
    } else {
      url = null;
    }

    return () => {
      cancelled = true;
      if (created) URL.revokeObjectURL(created);
      url = null;
    };
  });

  return {
    get url() {
      return url;
    },
  };
}
